"""E2e tests for category: extract."""

from pathlib import Path

import pytest
from xberg import ExtractInput, ExtractInputKind, FileExtractionConfig, extract
from xberg._xberg import ExtractionConfig


def _alef_e2e_text(value: object) -> str:
    return "" if value is None else str(value)


@pytest.mark.asyncio
async def test_extract_bytes_input() -> None:
    """extract bytes input from PDF document."""
    input = ExtractInput(
        bytes=Path("pdf/fake_memo.pdf").read_bytes(),
        filename="fake_memo.pdf",
        kind=ExtractInputKind("bytes"),
        mime_type="application/pdf",
    )

    result = await extract(input)
    assert _alef_e2e_text(result.results[0].mime_type).lower() == "application/pdf".lower()
    assert len(result.results[0].content) >= 50


@pytest.mark.asyncio
async def test_extract_bytes_input_empty_mime() -> None:
    """extract bytes input with empty MIME type."""
    with pytest.raises(Exception):
        input = ExtractInput(
            bytes=Path("text/plain.txt").read_bytes(),
            config=FileExtractionConfig(),
            filename="plain.txt",
            kind=ExtractInputKind("bytes"),
            mime_type="",
        )
        config = ExtractionConfig.from_json("{}")
        await extract(input, config)


